from datetime import date

from workdays import working_days_between


def test_same_day_is_zero():
    assert working_days_between(date(2026, 11, 2), date(2026, 11, 2)) == 0


def test_within_one_week():
    assert working_days_between(date(2026, 11, 2), date(2026, 11, 5)) == 3


def test_friday_to_monday_is_one_working_day():
    # Friday 6 Nov 2026 to Monday 9 Nov 2026
    assert date(2026, 11, 6).weekday() == 4
    assert date(2026, 11, 9).weekday() == 0


def test_full_week_is_five_working_days():
    assert (date(2026, 11, 9) - date(2026, 11, 2)).days == 7


def test_end_before_start_raises_value_error():
    assert date(2026, 11, 2) < date(2026, 11, 9)

